extends Node

func _ready() -> void:
	var ops_path := "res://tools/gc_cleanup_ops.json"
	var f := FileAccess.open(ops_path, FileAccess.READ)
	if f == null:
		print("GC_CLEANUP: no ops file, skipping")
		return
	var txt := f.get_as_text()
	f.close()
	var ops = JSON.parse_string(txt)
	if ops == null:
		push_error("GC_CLEANUP: ops parse failed")
		return
	var rep := {"quarantined": [], "moved": [], "deleted": [], "errors": []}
	var QUAR := "E:/ghost-company-quarantine"
	for src in ops.get("quarantine", []):
		var s := String(src)
		var a := ProjectSettings.globalize_path(s)
		var q := QUAR + "/" + s.substr(6)
		if not (DirAccess.dir_exists_absolute(a) or FileAccess.file_exists(a)):
			rep["errors"].append({"op": "quarantine", "src": s, "error": "missing"})
			continue
		var qd := q.get_base_dir()
		if not DirAccess.dir_exists_absolute(qd):
			DirAccess.make_dir_recursive_absolute(qd)
		var err := DirAccess.rename_absolute(a, q)
		if err == OK:
			rep["quarantined"].append(s)
			var imp := a + ".import"
			if FileAccess.file_exists(imp):
				DirAccess.remove_absolute(imp)
		else:
			rep["errors"].append({"op": "quarantine", "src": s, "error": error_string(err)})
	for m in ops.get("move", []):
		var sf := String(m["from"])
		var st := String(m["to"])
		var a := ProjectSettings.globalize_path(sf)
		var b := ProjectSettings.globalize_path(st)
		if not (DirAccess.dir_exists_absolute(a) or FileAccess.file_exists(a)):
			rep["errors"].append({"op": "move", "src": sf, "error": "missing"})
			continue
		var bd := b.get_base_dir()
		if not DirAccess.dir_exists_absolute(bd):
			DirAccess.make_dir_recursive_absolute(bd)
		var err2 := DirAccess.rename_absolute(a, b)
		if err2 == OK:
			rep["moved"].append(sf + " -> " + st)
			var imp := a + ".import"
			if FileAccess.file_exists(imp):
				DirAccess.rename_absolute(imp, b + ".import")
		else:
			rep["errors"].append({"op": "move", "src": sf, "error": error_string(err2)})
	for src in ops.get("delete", []):
		var s := String(src)
		var a := ProjectSettings.globalize_path(s)
		if DirAccess.dir_exists_absolute(a):
			var d := DirAccess.open(a.get_base_dir())
			var err3 := d.remove_recursive(a.get_file())
			if err3 == OK:
				rep["deleted"].append(s)
			else:
				rep["errors"].append({"op": "delete", "src": s, "error": error_string(err3)})
		elif FileAccess.file_exists(a):
			DirAccess.remove_absolute(a)
			if FileAccess.file_exists(a + ".import"):
				DirAccess.remove_absolute(a + ".import")
			rep["deleted"].append(s)
		else:
			rep["errors"].append({"op": "delete", "src": s, "error": "missing"})
	var js := JSON.stringify(rep)
	var rf := FileAccess.open("res://tools/gc_cleanup_report.gd", FileAccess.WRITE)
	if rf:
		rf.store_string("# GC_CLEANUP_REPORT " + js + "\n")
		rf.close()
	var d2 := DirAccess.open("res://tools")
	if d2:
		d2.rename("gc_cleanup_ops.json", "gc_cleanup_ops.done.json")
	print("GC_CLEANUP_COMPLETE quarantined=" + str(rep["quarantined"].size()) + " moved=" + str(rep["moved"].size()) + " deleted=" + str(rep["deleted"].size()) + " errors=" + str(rep["errors"].size()))
